#!/usr/bin/env bash
# Nexora Bot - Self-extracting installer
# Usage: sudo bash nexora-install.sh
# Or one-line: bash <(curl -s https://raw.githubusercontent.com/NexoraShield/Nexora/main/nexora-install.sh)
set -Eeuo pipefail

if [ "$(id -u)" -ne 0 ]; then
    echo "Run as root: sudo bash $0" >&2
    exit 1
fi

command -v unzip >/dev/null 2>&1 || { apt-get update -qq && apt-get install -y -qq unzip; }
command -v php >/dev/null 2>&1 || { echo "PHP is required. Install PHP first." >&2; exit 1; }

echo "==> Nexora Bot Installer"
echo "==> Extracting package..."

LINE=$(awk '/^__PAYLOAD_BELOW__$/{print NR+1; exit}' "$0")
TMPD=$(mktemp -d)
trap "rm -rf $TMPD" EXIT

tail -n +"$LINE" "$0" | base64 -d > "$TMPD/pkg.zip"
unzip -o -q "$TMPD/pkg.zip" -d "$TMPD/pkg"
cd "$TMPD/pkg"

# Regenerate manifest
find . -type f ! -name manifest.sha256 -print0 | sort -z | xargs -0 sha256sum | sed 's| \./| |' > manifest.sha256

bash install.sh "$@"

exit 0
